/// Validate typed owner before entering the lower planner and require its entire
/// computed pattern mapping at return. This performs no legacy owned conversion.
/// The lower adapter owns/admit/releases its plan/cache allocations via ctx.ledger.
pub fn plan_production_definition<'src>(
    planner: &mut dyn DefinitionPlanner,
    ctx: &mut DefinitionContext<'src, '_>,
    kind: DefinitionKind,
    element: ElementId,
    owner: DefinitionOwner,
    transform: Affine,
    bounds: [f64; 4],
    style: &CssPaint<'src>,
    control: &mut dyn WorkControl,
) -> Result<ProductionDefinitionPlan<'src>> {
    validate_production_plan(ctx, kind, element, owner, transform, bounds, style, control,
        |ctx, control| planner.plan_owned_definition(ctx, kind, element, owner, transform, bounds, style, control))
}

/// Nonpattern dispatch through the same combined operations object supplied to
/// `ChannelAwareProductionDecodeSession::step`. Pattern is rejected here so a
/// decoder cannot fall back to the compatibility planner without a channel.
pub fn plan_channel_aware_definition<'src>(
    planner: &mut dyn ChannelAwareProductionDecodeOperations,
    ctx: &mut DefinitionContext<'src, '_>,
    kind: DefinitionKind,
    element: ElementId,
    owner: DefinitionOwner,
    transform: Affine,
    bounds: [f64; 4],
    style: &CssPaint<'src>,
    control: &mut dyn WorkControl,
) -> Result<ProductionDefinitionPlan<'src>> {
    if kind == DefinitionKind::Pattern {
        return Err(invalid(0));
    }
    validate_production_plan(ctx, kind, element, owner, transform, bounds, style, control,
        |ctx, control| planner.plan_owned_definition(ctx, kind, element, owner, transform, bounds, style, control))
}

/// Required channel-aware production route for patterns. All source, owner,
/// style, bounds, returned descriptor/mapping, and post validation is shared
/// with the compatibility production entry point above.
pub fn plan_production_pattern<'src>(
    planner: &mut dyn PaintChannelDefinitionPlanner,
    ctx: &mut DefinitionContext<'src, '_>,
    element: ElementId,
    owner: DefinitionOwner,
    channel: PaintChannel,
    transform: Affine,
    bounds: [f64; 4],
    style: &CssPaint<'src>,
    control: &mut dyn WorkControl,
) -> Result<ProductionDefinitionPlan<'src>> {
    validate_production_plan(ctx, DefinitionKind::Pattern, element, owner, transform, bounds, style, control,
        |ctx, control| planner.plan_owned_pattern_definition(ctx, element, owner, channel, transform, bounds, style, control))
}

/// Pattern dispatch through a combined decoder operations object. The explicit
/// channel is mandatory and no compatibility planner is consulted.
pub fn plan_channel_aware_pattern<'src>(
    planner: &mut dyn ChannelAwareProductionDecodeOperations,
    ctx: &mut DefinitionContext<'src, '_>,
    element: ElementId,
    owner: DefinitionOwner,
    channel: PaintChannel,
    transform: Affine,
    bounds: [f64; 4],
    style: &CssPaint<'src>,
    control: &mut dyn WorkControl,
) -> Result<ProductionDefinitionPlan<'src>> {
    validate_production_plan(ctx, DefinitionKind::Pattern, element, owner, transform, bounds, style, control,
        |ctx, control| planner.plan_owned_pattern_definition(ctx, element, owner, channel, transform, bounds, style, control))
}

fn validate_production_plan<'src>(
    ctx: &mut DefinitionContext<'src, '_>,
    kind: DefinitionKind,
    element: ElementId,
    owner: DefinitionOwner,
    transform: Affine,
    bounds: [f64; 4],
    style: &CssPaint<'src>,
    control: &mut dyn WorkControl,
    plan: impl FnOnce(&mut DefinitionContext<'src, '_>, &mut dyn WorkControl) -> Result<ProductionDefinitionPlan<'src>>,
) -> Result<ProductionDefinitionPlan<'src>> {
    owner.validate(ctx)?;
    validate_style(ctx.shared.source(), style, control)?;
    ctx.shared
        .element(element, crate::memory::add(element.0, 1)?, control)?;
    // Preserve source/style validation priority, then bind the canonical
    // dispatched definition to its typed owner before either lower planner.
    if owner.element() != element {
        return Err(invalid(0));
    }
    if !vexel_geometry::affine_valid(transform)
        || !bounds.into_iter().all(f64::is_finite)
        || bounds[2] < 0.
        || bounds[3] < 0.
    {
        return Err(invalid(0));
    }
    let plan = plan(ctx, control)?;
    let (definition, mapping) = match &plan {
        ProductionDefinitionPlan::Definition(plan) => (plan, None),
        ProductionDefinitionPlan::Pattern { plan, mapping } => (plan, Some(*mapping)),
    };
    let actual = match &definition.descriptor {
        DefinitionDescriptor::Clip(_) => DefinitionKind::Clip,
        DefinitionDescriptor::Mask(_) => DefinitionKind::Mask,
        DefinitionDescriptor::Pattern(descriptor) => {
            if descriptor.definition != element {
                return Err(invalid(0));
            }
            let map = mapping.ok_or_else(|| invalid(0))?;
            map.pixel_inverse(*descriptor)?;
            let DefinitionTarget::Shape(shape) = owner.target else {
                return Err(invalid(0));
            };
            if ctx
                .builder
                .scene(ctx.scene)?
                .shape(shape)
                .ok_or_else(|| invalid(0))?
                .source
                != map.source_map
                || map.bounds != bounds
            {
                return Err(invalid(0));
            }
            DefinitionKind::Pattern
        }
        DefinitionDescriptor::Marker(_) => DefinitionKind::Marker,
        DefinitionDescriptor::Filter { filter, primitives } => {
            let DefinitionTarget::Group(_) = owner.target else {
                return Err(invalid(0));
            };
            crate::validate::filter(*filter, primitives, control)?;
            for p in primitives {
                control.charge(WorkKind::FilterPixel, 1).map_err(stopped)?;
                if p.source_offset > ctx.shared.source().len() {
                    return Err(invalid(p.source_offset));
                }
            }
            DefinitionKind::Filter
        }
    };
    if actual != kind || (kind != DefinitionKind::Pattern && mapping.is_some()) {
        return Err(invalid(0));
    }
    crate::mask_post::validate_production_post(ctx, kind, None, definition.post, control)?;
    if definition.expansions.len() > 65536 {
        return Err(crate::types::limit(LimitKind::References));
    }
    for expansion in &definition.expansions {
        crate::mask_post::validate_production_post(
            ctx,
            kind,
            Some(expansion.flavor),
            expansion.post,
            control,
        )?;
        control
            .charge(WorkKind::ReferenceProbe, 1)
            .map_err(stopped)?;
        expansion.range.require(ctx.shared.tokens().len(), 0)?;
        validate_style(ctx.shared.source(), &expansion.style, control)?;
        if !vexel_geometry::affine_valid(expansion.transform)
            || !expansion
                .viewport
                .into_iter()
                .all(|v| v.is_finite() && v > 0.)
        {
            return Err(invalid(0));
        }
    }
    control.checkpoint().map_err(stopped)?;
    Ok(plan)
}

fn validate_style(
    source: &[u8],
    style: &CssPaint<'_>,
    control: &mut dyn WorkControl,
) -> Result<()> {
    for property in vexel_svg_css::Property::ALL {
        control.charge(WorkKind::PaintVisit, 1).map_err(stopped)?;
        if let Some(value) = style.value(property) {
            let bytes = value
                .span
                .slice(source)
                .ok_or_else(|| invalid(value.span.offset))?;
            if bytes.as_ptr() != value.bytes.as_ptr() || bytes.len() != value.bytes.len() {
                return Err(invalid(value.span.offset));
            }
        }
    }
    Ok(())
}
//! Explicit production paint-channel handoff through real pattern publication.
mod support;
use support::*;
use std::sync::Arc;
use vexel_geometry::affine_identity as identity;
use vexel_scene::*;
use vexel_svg_css::Property;

fn element(doc: &LexicalDocument, name: &[u8]) -> ElementId {
    ElementId(doc.tokens().iter().position(|t| t.local_name.slice(doc.source()) == Some(name)).unwrap())
}

struct ChannelPlanner;
impl PaintChannelDefinitionPlanner for ChannelPlanner {
    fn plan_owned_pattern_definition<'src>(
        &mut self,
        ctx: &mut DefinitionContext<'src, '_>,
        element: ElementId,
        owner: DefinitionOwner,
        channel: PaintChannel,
        _: Affine,
        bounds: [f64; 4],
        style: &vexel_svg_css::CssPaint<'src>,
        _: &mut dyn WorkControl,
    ) -> Result<ProductionDefinitionPlan<'src>> {
        owner.validate(ctx)?;
        let property = match channel {
            PaintChannel::Fill => Property::FillOpacity,
            PaintChannel::Stroke => Property::StrokeOpacity,
        };
        let opacity = style.value(property).map_or(Ok(1.0), |value| {
            let bytes = value.span.slice(ctx.shared.source()).ok_or(Diagnostic {
                kind: ErrorKind::InvalidArgument,
                offset: value.span.offset,
            })?;
            std::str::from_utf8(bytes)
                .ok()
                .and_then(|value| value.parse::<f64>().ok())
                .ok_or(Diagnostic { kind: ErrorKind::InvalidArgument, offset: value.span.offset })
        })?;
        let DefinitionTarget::Shape(shape) = owner.target() else { unreachable!() };
        let source_map = ctx.builder.scene(ctx.scene)?.shape(shape).unwrap().source;
        let mapping = PatternMapping {
            tile_origin: [0., 0.], user_to_base: identity(), pattern_transform: identity(),
            user_inverse: identity(), viewport: [100., 100.], bounds, source_map, opacity,
        };
        let descriptor = PatternDescriptor {
            definition: element, width: 1, height: 1, tile_width: 1., tile_height: 1.,
            content_transform: identity(), error_offset: 0,
        };
        Ok(ProductionDefinitionPlan::Pattern {
            plan: DefinitionPlan {
                descriptor: DefinitionDescriptor::Pattern(descriptor),
                expansions: Vec::new(), post: PostOperation::None,
            },
            mapping,
        })
    }
}

/// One actual combined decoder fixture implements both retained-definition and
/// explicit-channel pattern dispatch used by a channel-aware session.
struct CombinedPlanner;
impl DefinitionPlanner for CombinedPlanner {
    fn plan_owned_definition<'src>(
        &mut self,
        ctx: &mut DefinitionContext<'src, '_>,
        kind: DefinitionKind,
        _element: ElementId,
        owner: DefinitionOwner,
        _: Affine,
        _: [f64; 4],
        _: &vexel_svg_css::CssPaint<'src>,
        _: &mut dyn WorkControl,
    ) -> Result<ProductionDefinitionPlan<'src>> {
        assert_eq!(kind, DefinitionKind::Filter);
        owner.validate(ctx)?;
        let DefinitionTarget::Group(group) = owner.target() else { panic!("filter requires group owner") };
        Ok(ProductionDefinitionPlan::Definition(DefinitionPlan {
            descriptor: DefinitionDescriptor::Filter { filter: filter(), primitives: vec![primitive()] },
            expansions: Vec::new(), post: PostOperation::FinishGroup(group),
        }))
    }
}
impl PaintChannelDefinitionPlanner for CombinedPlanner {
    fn plan_owned_pattern_definition<'src>(
        &mut self,
        ctx: &mut DefinitionContext<'src, '_>,
        element: ElementId,
        owner: DefinitionOwner,
        channel: PaintChannel,
        transform: Affine,
        bounds: [f64; 4],
        style: &vexel_svg_css::CssPaint<'src>,
        control: &mut dyn WorkControl,
    ) -> Result<ProductionDefinitionPlan<'src>> {
        ChannelPlanner.plan_owned_pattern_definition(ctx, element, owner, channel, transform, bounds, style, control)
    }
}
impl CachedPaintResolver for CombinedPlanner {
    fn resolve_cached<'cache>(
        &'cache mut self,
        _: &mut DecodeSource<'_>,
        _: &mut ChargeLedger,
        _: vexel_xml::XmlSpan,
